def letters():
    """Every non-ASCII character any language uses: tools/export_c.py adds them to the font."""
    chars = set()
    for v in S.values():
        for t in v.values():
            chars |= {c for c in t if ord(c) > 126}
    chars |= {c for n in NATIVE.values() for c in n if ord(c) > 126}
    return sorted(chars)
